interface Size {
  id: string | number;
  size_label: string;
  price: number;
}

interface Product {
  id: string | number;
  name: string;
  veg: boolean;
  available: boolean;
  description?: string;
  sizes: Size[];
}

interface Category {
  id: string | number;
  name: string;
  products: Product[];
}

interface MenuData {
  restaurant: {
    name: string;
    pure_veg: boolean;
  };
  categories: Category[];
}

interface PageParams {
  state: string;
  city: string;
  slug: string;
}

async function getMenu(state: string, city: string, slug: string): Promise<MenuData> {
  const res = await fetch(
    `${process.env.NEXT_PUBLIC_API_URL}/menu/${state}/${city}/${slug}`,
    { cache: "no-store" }
  );
  if (!res.ok) throw new Error("Menu not found");
  return res.json();
}

export default async function MenuPage({ params }: { params: PageParams }) {
  const { state, city, slug } = params;
  const data = await getMenu(state, city, slug);

  return (
    <div className="min-h-screen bg-white p-4">
      {/* Restaurant Header */}
      <div className="mb-4">
        <h1 className="text-xl font-bold">{data.restaurant.name}</h1>
        <p className="text-sm text-gray-500 capitalize">
          {city}, {state}
        </p>
      </div>

      {/* Veg / Non-Veg Info */}
      {data.restaurant.pure_veg && (
        <div className="mb-3 text-green-600 font-medium">
          🟢 Pure Veg Restaurant
        </div>
      )}

      {/* Menu */}
      <div className="space-y-6">
        {data.categories.map((cat: Category) => (
          <div key={cat.id}>
            <h2 className="text-lg font-semibold mb-2">
              {cat.name}
            </h2>

            <div className="space-y-3">
              {cat.products.map((item: Product) => (
                <div
                  key={item.id}
                  className="border-b pb-3 flex justify-between"
                >
                  <div>
                    <div className="font-medium">
                      {item.veg ? "🟢" : "🔴"} {item.name}
                    </div>

                    {!item.available && (
                      <div className="text-xs text-red-500">
                        Sold Out
                      </div>
                    )}

                    {item.description && (
                      <div className="text-sm text-gray-500">
                        {item.description}
                      </div>
                    )}
                  </div>

                  <div className="text-right text-sm">
                    {item.sizes.map((s: Size) => (
                      <div key={s.id}>
                        {s.size_label} ₹{s.price}
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
